import json, os
p='/home/data4/xiangyu/BioDSA/workdir/workdir/comprehensive_protein_function_and_localization_analysis_e5277698055c.protein.json'
with open(p) as f: d=json.load(f)
print('TOP_LEVEL_KEYS', list(d.keys()))
for k,v in d.items():
    if k in ['sequence','full_sequence']: continue
    if isinstance(v,(str,int,float,bool)) or v is None:
        print('\n',k,':',v)
    elif isinstance(v,list):
        print('\n',k,'LIST',len(v))
        for x in v[:15]: print(x)
    elif isinstance(v,dict):
        print('\n',k,'DICT_KEYS',list(v.keys()))
        print(json.dumps(v,indent=2)[:6000])
